import { describe, expect, it } from 'vitest'
import { analyze, convert } from './converter'

/**
 * Regression tests. Expected values were generated by the converter itself
 * (the author considers its current behaviour correct) from words of the Book of Genesis.
 * If a test fails after a rule change, check that the change is intended.
 */
describe('convert: single words', () => {
  it.each([
    ['בְּרֵאשִׁית', 'bereszit'],
    ['בָּרָא', 'bara'],
    ['אֱלֹהִים', 'elohim'],
    ['אֵת', 'et'],
    ['הַשָּׁמַיִם', 'haszamajim'],
    ['וְאֵת', 'weet'],
    ['הָאָרֶץ', 'haarec'],
    ['וַיֹּאמֶר', 'wajomer'],
    ['כִּי', 'ki'],
    ['טוֹב', 'tow'],
    ['לֹא', 'lo'],
    ['זֶה', 'ze'],
    ['סֵפֶר', 'sefer'],
    ['תּוֹלְדֹת', 'toldot'],
    ['הִנֵּנִי', 'hineni'],
    ['בְּנוֹ', 'beno'],
    ['הַגָּדֹל', 'hagadol'],
    ['וַיִּקְרָא', 'wajikra'],
    ['בְּיוֹם', 'bejom'],
    ['עֵינָיו', 'ejnaw'],
  ])('%s -> %s', (hebrew, phonetics) => {
    expect(convert(hebrew)).toBe(phonetics)
  })

  it('reads Het with Patach as "aH" only at the end of a word (furtive patach)', () => {
    expect(convert('מָשִׁיחַ')).toBe('masziaH')
    expect(convert('חַיַּת')).toBe('Hajat')
    expect(convert('חַ')).toBe('Ha')
  })

  it('reads the Tetragrammaton as "adonai"', () => {
    expect(convert('יְהוָה')).toBe('adonai')
  })
})

describe('convert: phrases', () => {
  it('separates words with a single space and drops punctuation', () => {
    expect(convert('בְּרֵאשִׁית, בָּרָא אֱלֹהִים, אֵת הַשָּׁמַיִם, וְאֵת הָאָרֶץ.')).toBe(
      'bereszit bara elohim et haszamajim weet haarec',
    )
  })

  it('treats maqaf (hyphen) as a word separator', () => {
    expect(convert('כִּי-טוֹב')).toBe('ki tow')
  })

  it('understands presentation forms (tav + dagesh as one character)', () => {
    expect(convert('תִּרְצָח')).toBe(convert('\uFB4A\u05B4רְצָח'))
    expect(convert('\uFB4A\u05B4רְצָח')).not.toBe('')
  })

  it('returns an empty string for text without Hebrew letters', () => {
    expect(convert('abc 123')).toBe('')
  })
})

describe('analyze', () => {
  it('returns one entry per word with Hebrew and phonetics', () => {
    const result = analyze('בְּרֵאשִׁית, בָּרָא')
    expect(result.map((w) => [w.hebrew, w.phonetics])).toEqual([
      ['בְּרֵאשִׁית', 'bereszit'],
      ['בָּרָא', 'bara'],
    ])
  })

  it('describes every letter and joins back to the word phonetics', () => {
    const [word] = analyze('בְּרֵאשִׁית')
    expect(word!.letters.map((l) => l.name)).toEqual(['Bet', 'Resz', 'Alef', 'Szin', 'Jod', 'Taw'])
    expect(word!.letters.map((l) => l.phonetics).join('')).toBe(word!.phonetics)
    // The first letter keeps its dagesz and nikud in the Hebrew rendering.
    expect(word!.letters[0]!.hebrew).toBe('בְּ')
  })

  it('shows silent letters with empty phonetics', () => {
    const [word] = analyze('בָּרָא')
    expect(word!.letters[word!.letters.length - 1]!.phonetics).toBe('')
  })

  it('marks the Tetragrammaton as a single part read as "adonai"', () => {
    const [word] = analyze('יְהוָה')
    expect(word!.isYHWH).toBe(true)
    expect(word!.letters).toHaveLength(1)
    expect(word!.letters[0]!.phonetics).toBe('adonai')
  })

  it('skips chunks without Hebrew letters', () => {
    expect(analyze('abc 123')).toEqual([])
  })
})
